#!/usr/bin/env python3
"""Generate MANAGE.md and the generated parts of the issue forms.

  - MANAGE.md: every speaking event (grouped by year → month), project and
    testimonial, plus recent activity by month, each with one-click
    "Update" / "Remove" links that open the matching issue form with the
    entry already filled in (issue forms pre-fill text fields from the URL).
  - update-*.yml: one "Update or remove" form per data type, with that type's
    own fields (TYPES[kind]["edit_inputs"] in issue_to_data.py).
  - add-speaking-event.yml: role checkboxes (between the roles:start /
    roles:end markers) from data/roles.json.

Run by issue-to-data.yml and edit-forms.yml whenever data changes.
"""
import json
import os
import re
from calendar import month_name
from urllib.parse import quote, urlencode

from issue_to_data import EDIT_FIELDS, ROLES, ROOT, TYPES, entry_labels

OUT = ROOT / ".github" / "ISSUE_TEMPLATE"
REPO = os.environ.get("GITHUB_REPOSITORY", "nomadicmehul/nomadicmehul.github.io")
FORMS = {"speaking": ("update-speaking-event.yml", "🎤"), "project": ("update-project.yml", "🚀"), "testimonial": ("update-testimonial.yml", "💬")}
ADD_FORMS = {"speaking": "add-speaking-event.yml", "project": "add-project.yml", "testimonial": "add-testimonial.yml"}
MANAGE_URL = f"https://github.com/{REPO}/blob/main/MANAGE.md"
GENERATED = "Generated by .github/scripts/build_manage.py — don't edit by hand."


def q(s):
    """Quote a string for YAML (JSON strings are valid YAML)."""
    return json.dumps(s, ensure_ascii=False)


# ---------- issue forms ----------

def field(widget, id_, label, help_):
    lines = []
    if widget in ("text", "list"):
        lines += ["  - type: input", f"    id: {id_}", "    attributes:", f"      label: {q(label)}"]
    elif widget == "textarea":
        lines += ["  - type: textarea", f"    id: {id_}", "    attributes:", f"      label: {q(label)}"]
    elif widget == "roles":
        lines += ["  - type: checkboxes", f"    id: {id_}", "    attributes:", f"      label: {q(label)}", "      options:"]
        lines += [f"        - label: {q(r)}" for r in ROLES]
    elif widget in ("bool", "stars"):
        options = ["Keep", "Yes", "No"] if widget == "bool" else ["Keep", "5", "4", "3", "2", "1"]
        lines += ["  - type: dropdown", f"    id: {id_}", "    attributes:", f"      label: {q(label)}", "      options:"]
        lines += [f"        - {q(o)}" for o in options]
        lines += ["      default: 0"]
    if help_:
        lines.append(f"      description: {q(help_)}")
    return lines


def render_form(kind):
    t, noun = TYPES[kind], TYPES[kind]["noun"]
    filename, emoji = FORMS[kind]
    entry_label = next(label for label, k in EDIT_FIELDS.items() if k == kind)
    lines = [
        f"# {GENERATED}",
        f"name: {q(f'{emoji} Update or remove {noun}')}",
        f"description: {q(f'Change or delete an existing {noun}. Easiest: open it from MANAGE.md, which fills in the entry for you.')}",
        f"title: {q(f'[edit] {noun}')}",
        'labels: ["data:edit"]',
        "body:",
        "  - type: markdown",
        "    attributes:",
        f"      value: {q(f'Fill in **only what should change** — blank fields keep their current value. Find entries by year and month in [MANAGE.md]({MANAGE_URL}). Only issues opened by the repo owner are processed.')}",
        "  - type: input",
        "    id: entry",
        "    attributes:",
        f"      label: {q(entry_label)}",
        f"      description: {q(f'Filled in when you open this from MANAGE.md. Typing works too: the title, or part of it if unique.')}",
        "    validations:",
        "      required: true",
        "  - type: dropdown",
        "    id: action",
        "    attributes:",
        "      label: Action",
        "      description: Remove deletes the whole entry and ignores the fields below",
        "      options:",
        "        - Update",
        "        - Remove",
        "      default: 0",
        "    validations:",
        "      required: true",
    ]
    for i, (label, key, widget, help_) in enumerate(t["edit_inputs"]):
        lines += field(widget, f"new_{i}", label, help_)
    if kind == "speaking":
        lines += [
            "  - type: textarea",
            "    id: add_resources",
            "    attributes:",
            "      label: Add resources",
            f"      description: {q('One per line: `type | url` or `type | label | url`. Types: event, slides, code, demo, video, blog. You can drag a PDF in for slides.')}",
            "      placeholder: |",
            "        video | https://youtube.com/watch?v=...",
            "        blog | My write-up | https://medium.com/@nomadicmehul/...",
            "  - type: input",
            "    id: remove_resources",
            "    attributes:",
            "      label: Remove resources",
            f"      description: {q('Comma-separated types to remove, e.g. `slides, demo`')}",
        ]
    (OUT / filename).write_text("\n".join(lines) + "\n")


def sync_add_form_roles():
    path = OUT / "add-speaking-event.yml"
    block = "      options:\n" + "".join(f"        - label: {q(r)}\n" for r in ROLES)
    s, n = re.subn(r"(# roles:start[^\n]*\n).*?(      # roles:end)", lambda m: m.group(1) + block + m.group(2), path.read_text(), flags=re.S)
    assert n == 1, "roles:start / roles:end markers missing from add-speaking-event.yml"
    path.write_text(s)


# ---------- MANAGE.md ----------

def issue_url(template, **params):
    return f"https://github.com/{REPO}/issues/new?" + urlencode({"template": template, **params}, quote_via=quote)


def actions(kind, label):
    form = FORMS[kind][0]
    update = issue_url(form, entry=label, title=f"[edit] {label}")
    remove = issue_url(form, entry=label, action="Remove", title=f"[remove] {label}")
    return f"[✏️ Update]({update}) · [🗑️ Remove]({remove})"


def cell(s):
    return str(s).replace("|", "\\|").replace("\n", " ")


def month_of(day):
    y, m = day[:4], int(day[5:7])
    return f"{month_name[m]} {y}"


def load(kind):
    data = json.loads((ROOT / TYPES[kind]["path"]).read_text())
    return data, entry_labels(kind, data)


def speaking_section(events, labels):
    out = [f"## 🎤 Speaking events ({len(events)})", "",
           f"Grouped by event date. [➕ Add speaking event]({issue_url(ADD_FORMS['speaking'])})", ""]
    by_year = {}
    for e, label in zip(events, labels):
        by_year.setdefault(str(e.get("year")), []).append((e, label))
    for i, (year, items) in enumerate(sorted(by_year.items(), reverse=True)):
        out += [f"<details{' open' if i == 0 else ''}>", f"<summary><b>{year}</b> — {len(items)} event{'s' * (len(items) != 1)}</summary>", ""]
        by_month = {}
        for e, label in items:
            by_month.setdefault(e.get("date", "")[:7], []).append((e, label))
        for ym, rows in sorted(by_month.items(), reverse=True):
            out += [f"#### {month_of(ym + '-01') if len(ym) == 7 else 'No date'}", "",
                    "| Date | Event | Location | Resources | Updated | |", "|---|---|---|---|---|---|"]
            for e, label in rows:
                res = ", ".join(r["type"] for r in e.get("resources", [])) or "—"
                out.append(f"| {e.get('date', '')} | {cell(e['title'])} | {cell(e.get('location', ''))} | {res} | {e.get('updated', '')} | {actions('speaking', label)} |")
            out.append("")
        out += ["</details>", ""]
    return out


def simple_section(kind, title, columns, row):
    data, labels = load(kind)
    out = [f"## {title} ({len(data)})", "",
           f"[➕ Add {TYPES[kind]['noun']}]({issue_url(ADD_FORMS[kind])})", "",
           "| " + " | ".join(columns) + " | Updated | |", "|" + "---|" * (len(columns) + 2)]
    out += [f"| {' | '.join(cell(c) for c in row(e))} | {e.get('updated', '')} | {actions(kind, label)} |" for e, label in zip(data, labels)]
    return out + [""]


def activity_section(months=6):
    rows = []
    for kind in TYPES:
        data, labels = load(kind)
        for e, label in zip(data, labels):
            if e.get("updated"):
                what = "Added" if e.get("added") == e["updated"] else "Updated"
                rows.append((e["updated"], what, TYPES[kind]["noun"], label, kind))
    rows.sort(reverse=True)
    out = ["## 🕒 Recent activity", "", "When entries were added or last changed, newest first.", ""]
    by_month = {}
    for r in rows:
        by_month.setdefault(r[0][:7], []).append(r)
    for ym in sorted(by_month, reverse=True)[:months]:
        out += [f"<details{' open' if ym == max(by_month) else ''}>", f"<summary><b>{month_of(ym + '-01')}</b> — {len(by_month[ym])} change{'s' * (len(by_month[ym]) != 1)}</summary>", "",
                "| Date | | Type | Entry | |", "|---|---|---|---|---|"]
        out += [f"| {day} | {what} | {noun} | {cell(label)} | {actions(kind, label)} |" for day, what, noun, label, kind in by_month[ym]]
        out += ["", "</details>", ""]
    return out


def render_manage():
    events, labels = load("speaking")
    counts = {k: len(load(k)[0]) for k in TYPES}
    latest = max((e.get("updated", "") for k in TYPES for e in load(k)[0]), default="")
    lines = [
        f"<!-- {GENERATED} -->",
        "# 🛠️ Manage site content",
        "",
        f"**{counts['speaking']}** speaking events · **{counts['project']}** projects · **{counts['testimonial']}** testimonials"
        f" — last change {latest}",
        "",
        f"**➕ Add:** [Speaking event]({issue_url(ADD_FORMS['speaking'])}) · [Project]({issue_url(ADD_FORMS['project'])}) · [Testimonial]({issue_url(ADD_FORMS['testimonial'])})",
        "",
        "**✏️ Update / 🗑️ Remove:** find the entry below and click its link. The form opens with the entry filled in;"
        " change only what's needed and submit. For **Remove**, check that *Action* says Remove before submitting.",
        "",
        "Every submission is validated, committed to `data/*.json`, and the site redeploys in a minute or two."
        " Blog posts sync from Medium automatically and aren't listed here.",
        "",
        "**Jump to:** [Recent activity](#-recent-activity) · [Speaking events](#-speaking-events-" + str(counts['speaking']) + ")"
        f" · [Projects](#-projects-{counts['project']}) · [Testimonials](#-testimonials-{counts['testimonial']})",
        "",
    ]
    lines += activity_section()
    lines += speaking_section(events, labels)
    lines += simple_section("project", "🚀 Projects", ["Project", "Tech", "Featured"],
                            lambda e: [e["title"], ", ".join(e.get("tech", [])), "⭐" if e.get("featured") else ""])
    lines += simple_section("testimonial", "💬 Testimonials", ["Name", "Role", "Stars"],
                            lambda e: [e["name"], e["role"], "★" * e.get("stars", 0)])
    (ROOT / "MANAGE.md").write_text("\n".join(lines))


def main():
    sync_add_form_roles()
    for kind in FORMS:
        render_form(kind)
    render_manage()
    print("Generated MANAGE.md, update-*.yml forms, and role checkboxes")


if __name__ == "__main__":
    main()
